import Foundation

/// The Game Center achievements as Play Games knows them: its project's ID,
/// and each achievement's Play ID and, for one that counts, how many steps
/// it takes. Generated by `Tools/Play/games.js` into
/// `Tools/Play/PlayGames/PlayGamesAchievements.json` once the achievements
/// exist on Play, and packed into the APK.
///
///     {"applicationId": "123456789012",
///      "achievements": {"com.example.game.achievement.levels.10":
///                         {"id": "CgkI…", "steps": 10}, …},
///      "leaderboards": {"com.example.game.leaderboard.score":
///                         {"id": "CgkI…"}, …}}
///
/// No `steps` (or 0) is a standard achievement, unlocked at 100%. A game
/// with no leaderboards leaves `leaderboards` out.
public struct PlayGamesMapping: Equatable, Sendable {
    public struct Entry: Equatable, Sendable {
        public var id: String
        public var steps: Int

        public init(id: String, steps: Int = 0) {
            self.id = id
            self.steps = steps
        }
    }

    public var applicationID: String
    /// By Game Center ID (`Achievement.id`).
    public var achievements: [String: Entry]
    /// Play's leaderboard ID, by Game Center leaderboard ID.
    public var leaderboards: [String: String]

    public init(applicationID: String, achievements: [String: Entry], leaderboards: [String: String] = [:]) {
        self.applicationID = applicationID
        self.achievements = achievements
        self.leaderboards = leaderboards
    }

    public init?(data: Data) {
        guard let root = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
              let applicationID = root["applicationId"] as? String, !applicationID.isEmpty
        else { return nil }
        let entries = root["achievements"] as? [String: [String: Any]] ?? [:]
        self.applicationID = applicationID
        achievements = entries.compactMapValues { entry -> Entry? in
            guard let id = entry["id"] as? String, !id.isEmpty else { return nil }
            return Entry(id: id, steps: entry.int("steps") ?? 0)
        }
        let boards = root["leaderboards"] as? [String: [String: Any]] ?? [:]
        leaderboards = boards.compactMapValues { entry -> String? in
            guard let id = entry["id"] as? String, !id.isEmpty else { return nil }
            return id
        }
    }

    /// What Play takes for a Game Center percentage: steps for one that
    /// counts, an unlock for one that doesn't (nil while it isn't earned).
    ///
    /// Game Center's percentages are whole, rounded down (`Achievement`), so
    /// for up to a hundred steps rounding back up gives the very count that
    /// made them; past a hundred the mapping counts in percent instead.
    public func report(_ percent: Double, for entry: Entry) -> (unlock: Bool, steps: Int?)? {
        if entry.steps <= 0 {
            return percent >= 100 ? (true, nil) : nil
        }
        let steps = min(entry.steps, Int((percent * Double(entry.steps) / 100 - 1e-9).rounded(.up)))
        return steps > 0 ? (false, steps) : nil
    }

    /// The Game Center percentage a Play achievement stands at.
    public func percent(unlocked: Bool, currentSteps: Int, of entry: Entry) -> Double {
        if unlocked { return 100 }
        guard entry.steps > 0 else { return 0 }
        return (Double(min(currentSteps, entry.steps)) / Double(entry.steps) * 100).rounded(.down)
    }
}

/// Play Games Services v2 behind `AchievementsBackend`, the shape
/// `GameCenterManager` already reports through: sign-in, what Play holds,
/// sending what has moved, the dashboard (the title's Play Games button) and
/// the player for a credit.
///
/// Sign-in is v2's own: a returning player is signed in by Play Games as the
/// app starts, without a sheet, and the game asks nothing of anyone who isn't
/// — play never waits on it. `answered` runs at the first answer, and again
/// each time the player becomes signed in (from Play Games' own app, or the
/// dashboard's button), which has `GameCenterManager` catch up then.
public final class PlayGamesAchievements: AchievementsBackend {
    private static let service = "games"

    private let channel: PlatformChannel
    private let mapping: PlayGamesMapping
    private var answered: (() -> Void)?
    private var nextRequest = 1
    private var loadWaiters: [CheckedContinuation<[String: Double], Never>] = []
    private var reportWaiters: [Int: CheckedContinuation<Bool, Never>] = [:]
    private var playerWaiters: [CheckedContinuation<(name: String, photo: Data?)?, Never>] = []

    public private(set) var isSignedIn = false
    /// Whether Play Games can run on this device (Google Play services there
    /// and up to date), as Java answers once at launch.
    public let hasDashboard: Bool
    /// Called whenever sign-in changes, for anything else riding on it
    /// (Saved Games).
    public var signInChanged: ((Bool) -> Void)?
    /// The signed-in player's Play Games ID and name, which Java sends just
    /// after each sign-in; nil while signed out. The beta's solve log names
    /// its records by them (`GKLocalPlayer` on Android).
    public private(set) var identity: (id: String, name: String)?
    /// Called whenever `identity` changes.
    public var identityChanged: (((id: String, name: String)?) -> Void)?

    public init(channel: PlatformChannel, mapping: PlayGamesMapping) {
        self.channel = channel
        self.mapping = mapping
        hasDashboard = channel.call("games.available")?.bool("available") ?? false
        channel.on(Self.service) { [weak self] event, body in self?.handle(event, body) }
    }

    public func start(answered: @escaping () -> Void) {
        self.answered = answered
        channel.call("games.start")
    }

    /// On the main actor, as Play's answers are delivered there
    /// (`PlatformBridge`): run off it, as a nonisolated `async` method
    /// does, it called into Java and changed the waiters from a
    /// libdispatch worker while the frame thread handled events.
    @MainActor
    public func load() async -> [String: Double] {
        guard isSignedIn else { return [:] }
        return await withCheckedContinuation { continuation in
            let first = loadWaiters.isEmpty
            loadWaiters.append(continuation)
            if first { channel.call("games.loadAchievements") }
        }
    }

    @MainActor
    public func report(_ progress: [String: Double], showingBanners: Bool) async -> Bool {
        guard isSignedIn else { return false }
        var items: [[String: Any]] = []
        for (id, percent) in progress.sorted(by: { $0.key < $1.key }) {
            guard let entry = mapping.achievements[id], let report = mapping.report(percent, for: entry) else { continue }
            var item: [String: Any] = ["id": entry.id]
            if report.unlock { item["unlock"] = true }
            if let steps = report.steps { item["steps"] = steps }
            items.append(item)
        }
        guard !items.isEmpty else { return true }
        let request = nextRequest
        nextRequest += 1
        return await withCheckedContinuation { continuation in
            reportWaiters[request] = continuation
            channel.call("games.report", ["items": items, "request": request])
        }
    }

    /// Play Games has no reset a player's game can call (its management API
    /// resets testers only), so `-ResetAchievements` resets nothing here.
    public func reset() async -> Bool { false }

    /// Play Games' achievements, over the game. Signed out, Java signs the
    /// player in first and opens them once that's done.
    public func showDashboard() {
        guard hasDashboard else { return }
        channel.call("games.showAchievements")
    }

    @MainActor
    public func localPlayer() async -> (name: String, photo: Data?)? {
        guard isSignedIn else { return nil }
        return await withCheckedContinuation { (continuation: CheckedContinuation<(name: String, photo: Data?)?, Never>) in
            let first = playerWaiters.isEmpty
            playerWaiters.append(continuation)
            if first { channel.call("games.player") }
        }
    }

    private func handle(_ event: String, _ body: PlatformChannel.Message) {
        switch event {
        case "signIn":
            let signedIn = body.bool("signedIn") ?? false
            let changed = signedIn != isSignedIn
            isSignedIn = signedIn
            if changed { signInChanged?(signedIn) }
            if !signedIn, identity != nil {
                identity = nil
                identityChanged?(nil)
            }
            // The first answer, whatever it is, and every sign-in after it.
            if let answered, changed || !hasAnswered {
                hasAnswered = true
                answered()
            }
        case "achievements":
            var held: [String: Double] = [:]
            if body.bool("ok") == true {
                let byPlayID = Dictionary(mapping.achievements.map { ($0.value.id, ($0.key, $0.value)) }, uniquingKeysWith: { first, _ in first })
                for item in body["items"] as? [PlatformChannel.Message] ?? [] {
                    guard let playID = item["id"] as? String, let (id, entry) = byPlayID[playID] else { continue }
                    held[id] = mapping.percent(unlocked: item.bool("unlocked") ?? false, currentSteps: item.int("currentSteps") ?? 0, of: entry)
                }
            }
            let waiters = loadWaiters
            loadWaiters = []
            for waiter in waiters { waiter.resume(returning: held) }
        case "reported":
            guard let request = body.int("request"), let waiter = reportWaiters.removeValue(forKey: request) else { return }
            waiter.resume(returning: body.bool("ok") ?? false)
        case "identity":
            guard isSignedIn, let id = body["id"] as? String, !id.isEmpty else { return }
            identity = (id, body["name"] as? String ?? "")
            identityChanged?(identity)
        case "player":
            var player: (name: String, photo: Data?)?
            if body.bool("ok") == true, let name = body["name"] as? String {
                player = (name, (body["photo"] as? String).flatMap { Data(base64Encoded: $0) })
            }
            let waiters = playerWaiters
            playerWaiters = []
            for waiter in waiters { waiter.resume(returning: player) }
        default:
            break
        }
    }

    private var hasAnswered = false
}
